solution.solution.cpp:
#include <map>
#include <string>
#include <vector>

std::vector<std::string> ordinalProblems(const std::map<std::string, int>& oldVersion, const std::map<std::string, int>& newVersion)
{
    std::vector<std::string> problems;
    std::map<int, std::string> oldByOrdinal;
    for (const auto& [name, ordinal] : oldVersion)
    {
        oldByOrdinal[ordinal] = name;
        const auto now{ newVersion.find(name) };
        if (now == newVersion.end()) problems.push_back(name + " was removed");
        else if (now->second != ordinal) problems.push_back(name + " moved from @" + std::to_string(ordinal) + " to @" + std::to_string(now->second));
    }
    for (const auto& [name, ordinal] : newVersion)
    {
        if (oldVersion.count(name)) continue;
        const auto was{ oldByOrdinal.find(ordinal) };
        if (was != oldByOrdinal.end()) problems.push_back("@" + std::to_string(ordinal) + " now means " + name + ", was " + was->second);
    }
    return problems;
}

unitTests:
using Table = std::map<std::string, int>;
using Lines = std::vector<std::string>;
TEST("the example") { CHECK_EQ(ordinalProblems(Table{ {"stackHeight", 1}, {"stackWeight", 2}, {"debugDump", 3} }, Table{ {"stackHeight", 1}, {"stackWeight", 5}, {"layers", 3} }), (Lines{ "debugDump was removed", "stackWeight moved from @2 to @5", "@3 now means layers, was debugDump" })); }
TEST("nothing changed") { CHECK(ordinalProblems(Table{ {"a", 1}, {"b", 2} }, Table{ {"a", 1}, {"b", 2} }).empty()); }
TEST("only additions on new ordinals") { CHECK(ordinalProblems(Table{ {"a", 1} }, Table{ {"a", 1}, {"b", 2}, {"c", 3} }).empty()); }
TEST("swapped") { CHECK_EQ(ordinalProblems(Table{ {"a", 1}, {"b", 2} }, Table{ {"a", 2}, {"b", 1} }), (Lines{ "a moved from @1 to @2", "b moved from @2 to @1" })); }
TEST("renamed") { CHECK_EQ(ordinalProblems(Table{ {"old", 4} }, Table{ {"fresh", 4} }), (Lines{ "old was removed", "@4 now means fresh, was old" })); }

